class Solution {
    public void reverseString(char[] s) {
        int left = 0;
        int right = s.length - 1;
        while (left < right) {
            char temp = s[left];
            s[left] = s[right];
            s[right] = temp;
            left++;
            right--;
        }
    }
}

class Solution {
    public void reverseString(char[] s) {
        int n = s.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char temp = s[i];
            s[i] = s[j];
            s[j] = temp;
        }
    }
}

class Solution {
    public void reverseString(char[] s) {
        int left = 0;
        int right = s.length - 1;
        while (left < right) {
            s[left] = (char) (s[left] ^ s[right]);
            s[right] = (char) (s[left] ^ s[right]);
            s[left] = (char) (s[left] ^ s[right]);
            left++;
            right--;
        }
    }
}

class Solution {
    public void reverseString(char[] s) {
        int left = 0;
        int right = s.length - 1;
        while (left < right) {
            s[left] = (char) (s[left] + s[right]);
            s[right] = (char) (s[left] - s[right]);
            s[left] = (char) (s[left] - s[right]);
            left++;
            right--;
        }
    }
}

class Solution {
    public void reverseString(char[] s) {
        for (int end = s.length - 1; end > 0; end--) {
            for (int i = 0; i < end; i++) {
                char temp = s[i];
                s[i] = s[i + 1];
                s[i + 1] = temp;
            }
        }
    }
}
